export async function getPrompt(name, args = {}) {
  if (name !== 'deploy_notice') {
    const err = new Error(`Unknown prompt: ${name}`);
    err.code = -32602;
    throw err;
  }
  const {service, version, ...rest} = args;
  // reject missing/empty
  if (service === undefined || service === null || String(service).trim() === '') {
    const err = new Error('service is required');
    err.code = -32602;
    throw err;
  }
  if (version === undefined || version === null || String(version).trim() === '') {
    const err = new Error('version is required');
    err.code = -32602;
    throw err;
  }
  // reject extra arguments
  if (Object.keys(rest).length > 0) {
