    err.code = -32602;
    throw err;
  }
  return {
    messages: [
      {role: 'user', content: {type: 'text', text: `Deploying service ${service} version ${version}.`}},
      {role: 'assistant', content: {type: 'text', text: `Acknowledged: ${service} ${version} deployment notice received.`}},
